  "입니다. 표시·아이콘·사용 패턴은 좌측 [뷰어 — TY Viewer]/[뷰어 — In Viewer] 탭에서 뷰어별로 설정하며, 기능은 두 뷰어 동일합니다.": "هي. يُضبط العرض والأيقونات وأنماط الاستخدام لكل عارض من تبويبي [العارض — TY Viewer]/[العارض — In Viewer] يسارًا، والوظائف متطابقة في العارضين.",
  "영상 파이프라인": "خط أنابيب الصور",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "خط فك ترميز WASM (بيتا) — فك ترميز البكسلات الأصلية (WADO-RS bulkdata) مباشرة في المتصفح",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "عند التفعيل يستقبل عارض 2D الإطارات الأصلية 16bit بدلًا من عرض الخادم (JPEG) ويفك ترميزها بمرمّز WASM. تنعكس تعديلات W/L فورًا دون ذهاب وإياب للخادم، ويُستقبل بصيغة النقل المحددة في إعدادات المستشفى (JPEG2000/JPEG-LS). قبل فك الترميز يُعرض بعرض الخادم (احتياطي تلقائي).",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "ملف تعريف وضع المنتج (05 Mode Profile — JSON خادمي)",
