  "현재 워크리스트·뷰어 레이아웃(컬럼·검색필드·팔레트/썸네일 배치·선택 뷰어)을 선택한 프로파일에 저장 (전역)": "حفظ تخطيط قائمة العمل والعارض الحالي (الأعمدة·حقول البحث·مواضع اللوحة/المصغّرات·العارض المحدد) في الملف التعريفي المختار (عام)",
