  "프로파일에 저장할까요? (전역 — 모든 사용자에게 적용)": "هل تريد حفظه في الملف التعريفي؟ (عام — يُطبَّق على كل المستخدمين)",
  "프로파일에 저장했습니다 (전역)": "حُفظ في الملف التعريفي (عام)",
  "현재 화면을 프로파일에 저장": "حفظ الشاشة الحالية في الملف التعريفي",
  "Core 기능은 동일, 화면 구성(컬럼·검색필드·팔레트/썸네일 배치·더블클릭·선택 뷰어)만 제품별 프로파일로 전환 — 타 PACS 사용 경험 그대로 이전. 프로파일 정의는 서버 전역 설정(mode.profiles)에서 로드.": "وظائف Core متطابقة؛ يتبدل فقط تكوين الشاشة (الأعمدة·حقول البحث·مواضع اللوحة/المصغّرات·النقر المزدوج·العارض المحدد) حسب الملف التعريفي للمنتج — نقل تجربة استخدام PACS آخر كما هي. تُحمَّل تعريفات الملفات من الإعدادات العامة للخادم (mode.profiles).",
  "=INFINITT 스타일 레이아웃 저장소 ·": "=مخزن تخطيط بنمط INFINITT ·",
