  "에서만 동작합니다. W/L 을 조정하는 동안에는 서버 렌더로 자동 폴백합니다(저장본은 검사 기본 W/L 로 구운 영상이라 그대로 쓰면 표시 W/L 과 실제 영상이 어긋납니다).": "يعمل فقط فيه. أثناء ضبط W/L يعود تلقائيًا إلى عرض الخادم (النسخة المخزنة مبنية بـ W/L الافتراضي للفحص، واستخدامها كما هي يسبب تعارضًا بين W/L المعروض والصورة الفعلية).",
