  "그 검사를 워크리스트에서 열면 그때 다시 받습니다(상한·삭제 기준을 바꾸거나 [지금 비우기] 를 눌러도 초기화됩니다).": "يُجلب مجددًا عند فتحه من قائمة العمل (يُعاد الضبط أيضًا عند تغيير الحد·معيار الحذف أو الضغط على [إفراغ الآن]).",
