  "% 를 넘으면 알립니다 —": "يُنبَّه عند تجاوز % —",
  "다운로드가 곧 중지될 때만": "فقط عندما يوشك التنزيل على التوقف",
  "뜹니다(자동 삭제가 꺼져 있거나, 열려 있는 검사만으로 상한을 넘어 지울 것이 없을 때). 자동 삭제가 정상 작동 중이면 사용량이 상한에 붙어 있는 것이 정상이라 알리지 않습니다. 워크리스트 창에서 1회 — 판독 중인 뷰어 창에는 띄우지 않습니다.": "يظهر (عند إيقاف الحذف التلقائي، أو عندما تتجاوز الفحوصات المفتوحة وحدها الحد فلا شيء للحذف). إذا كان الحذف التلقائي يعمل فبقاء الاستخدام قرب الحد طبيعي ولا يُنبَّه. مرة واحدة في نافذة قائمة العمل — لا يظهر في نافذة العارض أثناء القراءة.",
