  ". MG 에서 계측을 쓰신다면 이 체크를 켜서 Series Layout 으로 두세요(뷰 하나당 페인 하나 — W/L·확대·계측이 뷰마다 따로 동작합니다). I-View 는 타일에도 계측이 나오므로 영향이 없습니다.": ". إن كنت تستخدم القياس في MG ففعّل هذا التحديد واجعله Series Layout (لوح لكل منظر — يعمل W/L والتكبير والقياس لكل منظر على حدة). I-View يعرض القياسات في التبليط أيضًا فلا يتأثر.",
