  "자동 — 영상에서 조직 경계를 찾아 잘라냄 (권장)": "تلقائي — إيجاد حدود النسيج في الصورة وقصها (موصى به)",
  "고정 비율 — 안쪽에서 정해진 비율만큼 잘라냄": "نسبة ثابتة — قص نسبة محددة من الداخل",
