  "· 우클릭(클릭만)=컨텍스트 메뉴 · 중클릭 드래그=Pan 고정 · 고정 키: Esc(계층 취소) · 1~9(시리즈 선택) · T 홀드(오버레이) · Backspace(주석 삭제 보조)": "· نقرة يمنى (نقرة فقط)=قائمة السياق · سحب بالزر الأوسط=Pan ثابت · مفاتيح ثابتة: Esc (إلغاء تدريجي) · 1~9 (اختيار سلسلة) · الاستمرار على T (الطبقة المعلوماتية) · Backspace (مساعد حذف التعليقات)",
