  "포트는 병원마다 자동 배정(상이)됩니다. ⚠ 단일 Orthanc는 DICOM 포트가 하나라, 실제 병원별 포트 리스닝은 병원별 Orthanc 인스턴스 또는 DICOM 라우터 배치가 필요합니다(여기서는 구성·연결 점검).": "تُخصص المنافذ تلقائيًا لكل مستشفى (مختلفة). ⚠ ‏Orthanc الواحد له منفذ DICOM واحد، لذا يتطلب الاستماع الفعلي لكل مستشفى نسخة Orthanc لكل مستشفى أو نشر موجّه DICOM (هنا فحص التكوين والاتصال فقط).",
