  "으로 바뀝니다. 부위·출처·Projection·설명은 유지되고, 위 두 체크박스는 기존 값을 불러왔습니다.": "ستتغير. تبقى منطقة الجسم والمصدر وProjection والوصف، وحُمّلت القيم الحالية لمربعي التحديد أعلاه.",
  "저장되는 것: 이 모니터 · Series/Image 레이아웃 · 칸별 시리즈 · 칸별 과거검사 기간. 3D 창과 다른 모니터 창의 구성은 저장되지 않습니다(같은 이름으로 각 창에서 저장하면 합쳐집니다).": "ما يُحفظ: هذه الشاشة · تخطيط Series/Image · سلسلة كل خانة · مدة الفحص السابق لكل خانة. لا يُحفظ تكوين نافذة 3D ونوافذ الشاشات الأخرى (بالحفظ بنفس الاسم من كل نافذة تُدمج).",
