  "건을 판독 주석으로 채택했습니다": " عنصرًا تم اعتمادها كتعليقات قراءة",
  "채택할 표시가 없습니다": "لا توجد علامات للاعتماد",
  "채택 실패": "فشل الاعتماد",
  "초대 시 자동으로 줄 기본 권한": "الصلاحيات الافتراضية عند الدعوة",
  "여기서 정한 것은 기본값입니다. 협진 중에는 협진 페이지에서 참가자마다 켜고 끌 수 있습니다.": "هذه قيم افتراضية. أثناء الجلسة يمكنك تفعيلها لكل مشارك من لوحة القراءة المشتركة.",
  "판독 수정·영상 삭제는 협진으로 절대 위임되지 않습니다 — 목록에 없는 이유입니다.": "لا يتم تفويض تعديل التقرير أو حذف الصور مطلقًا — لهذا لا تظهر في القائمة.",
  "화면 조작 · 발표자": "التحكم بالشاشة · مقدّم العرض",
  "참가 시 발표자 화면 따라가기 (내가 화면을 만지면 자유 보기로 전환)": "متابعة مقدّم العرض عند الانضمام (لمس العرض يحوّل إلى عرض حر)",
  "참가자의 권한 요청을 자동 승인": "الموافقة التلقائية على طلبات الصلاحيات",
  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "مقدّم العرض وحده يبثّ التحكم بالشاشة (تكبير/تحريك/W-L). ويتصفح الآخرون بحرية، بينما تُشارَك التعليقات والمؤشرات مع الجميع دائمًا.",
  "참여자 표시": "عرض المشاركين",
  "마우스 커서 옆에 참여자 아이디 표시": "إظهار معرّف المشارك بجوار مؤشر الفأرة",
  "참여자별 색으로 커서·툴·글자 구분": "تمييز المؤشر والأدوات والنص بلون كل مشارك",
  "화상·음성 네트워크 (STUN/TURN)": "شبكة الفيديو والصوت (STUN/TURN)",
  "병원 내부망은 비워 두면 됩니다. 인터넷을 건너는 협진에만 STUN/TURN 을 넣으세요 (JSON 배열).": "اتركه فارغًا داخل شبكة المستشفى. أضف STUN/TURN فقط للقراءة المشتركة عبر الإنترنت (مصفوفة JSON).",
  "계측·주석 그리기 (세션 한정 — 판독에는 Master 채택 시에만 저장)": "رسم القياسات والتعليقات (ضمن الجلسة فقط — تُحفظ في التقرير عند اعتماد Master فقط)",
  "텍스트·글쓰기 (세션 한정)": "النص والكتابة (ضمن الجلسة فقط)",
  "검사 탭 전환·과거 검사 열기": "تبديل تبويبات الفحص / فتح الفحوص السابقة",
  "적용 순서(고정)": "ترتيب التطبيق (ثابت)",
  ": ① 행잉(HP — 선택 시만) → ② Mammo(2D-MG — 선택 시만) → ③ 이 Common 표 → ④ 각 뷰어별 표 → ⑤ 자동 규칙(1×1 등).": ": ① بروتوكول العرض (HP — فقط عند اختياره) → ② الماموغرام (2D-MG — فقط عند اختياره) → ③ جدول Common هذا → ④ جدول كل عارض → ⑤ القواعد التلقائية (1×1 وغيرها).",
  "이 표에 해당 모달리티 행이 있으면 세 뷰어(SaintView/I-View/T-View) 모두 이 값을 씁니다. 행이 없으면 그 뷰어의 개별 표를 봅니다.": "إذا كان في هذا الجدول صف للوسيلة، تستخدمه العارضات الثلاث (SaintView/I-View/T-View). وإن لم يوجد، يُرجَع إلى جدول العارض نفسه.",
  "규정이 켜져 있을 때만 그 규정을 따릅니다(이 표에 MG 행이 없는 이유).": "يُطبَّق فقط عندما تكون تلك القاعدة مفعّلة (لهذا لا يوجد صف MG في هذا الجدول).",
  "행은 그 표에 행이 없는 나머지 모달리티에 적용됩니다 —": "ينطبق على بقية الوسائل غير الموجودة في ذلك الجدول —",
  "적용 순서(고정): Common 표에 그 모달리티 행이 있으면 Common 이 우선하고, 없을 때 이 표가 적용됩니다.": "الترتيب (ثابت): إذا كان في جدول Common صف للوسيلة فالأولوية له؛ ولا يُطبَّق هذا الجدول إلا عند غيابه.",
  ")는 아래": ") يتبع القاعدة أدناه",
  "별도 창으로 크게 보기 (다른 모니터로 옮길 수 있습니다)": "فتح في نافذة منفصلة (يمكن نقلها إلى شاشة أخرى)",
  "팝업이 차단되었습니다 — 이 사이트의 팝업을 허용해 주세요": "تم حظر النافذة المنبثقة — يرجى السماح بالنوافذ المنبثقة لهذا الموقع",
  "협진 패널 숨기기 (오른쪽으로 접기)": "إخفاء لوحة القراءة المشتركة (طيّها إلى اليمين)",
  "협진 패널 펼치기": "إظهار لوحة القراءة المشتركة",
  "드래그하면 폭이 바뀝니다 (더블클릭 = 기본 폭)": "اسحب لتغيير العرض (نقر مزدوج = العرض الافتراضي)",
  "좌우 비율 무시": "تجاهل نسبة اليمين/اليسار",
  "조직 탐지와 무관하게 항상 같은 고정 비율로 가운데 여백 제거 (기본 켬)": "اقتصاص الفراغ الأوسط دائمًا بنسبة ثابتة واحدة بغضّ النظر عن كشف الأنسجة (مفعّل افتراضيًا)",
  "자동 탐지가 영상마다 실패·지연하면 배치가 들쭉날쭉해집니다 — 켜 두면 항상 같은 모양으로 나옵니다. 해제하면 아래 흉벽 판정(자동 탐지) 규칙을 씁니다.": "عندما يفشل الكشف التلقائي أو يتأخر في بعض الصور يصبح الترتيب غير متسق — أبقِه مفعّلًا لمظهر ثابت. ألغِ التحديد لاستخدام قواعد تحديد جدار الصدر أدناه.",
  "드래그 = 컬럼 위치 이동 · 오른쪽 가장자리 드래그 = 폭 조절": "اسحب = نقل العمود · اسحب الحافة اليمنى = تغيير العرض",
  "나이": "العمر",
  "전문의 번호": "رقم الاختصاصي",
  "전문의 제": "اختصاصي رقم ",
  "원격 PACS 계정으로 로그인하면 면허·전문의 번호가 자동으로 채워집니다(등록이 없으면 공란).": "تسجيل الدخول بحساب PACS البعيد يملأ رقمي الرخصة والاختصاص تلقائيًا (فارغ إن لم يكونا مسجّلين).",
  "무대에 크게 — 이 화면 위에 함께 표시할 수 있습니다": "افتح على المنصة — يمكنكم التعليق على هذه الشاشة معًا",
  "내 화면을 전원에게 보여 줍니다 — 지금 발표 중인 사람에게서 넘겨받습니다": "اعرض شاشتك على الجميع — تنتقل الإدارة من مقدّم العرض الحالي",
