  "앞단(nginx)이 WebSocket 만 막고 있습니다": "الوكيل الأمامي (nginx) يحظر WebSocket فقط",
  "이 점검은 서버 응답을 받았습니다(REST 정상). 그런데 서버가 협진 소켓을 한 번도 수락하지 못했습니다 — 업그레이드 요청이 백엔드에 도달하지 않는다는 뜻입니다.": "تلقّى هذا الفحص استجابة من الخادم (REST يعمل)، لكن الخادم لم يقبل قط مقبس القراءة المشتركة — أي أن طلب الترقية لا يصل إلى الخلفية.",
  "서버 자가 점검에 실패했습니다 — REST 도 되지 않습니다(서버·네트워크 확인).": "فشل الفحص الذاتي للخادم — حتى REST لا يستجيب (تحقّق من الخادم والشبكة).",
