  "전체 사용자": "كل المستخدمين",
  "서버": "الخادم",
  "이 기록은 화면이 '서버가 막고 있다'고 판정한 순간 서버에 남습니다. 같은 원인은 5분에 한 번만 기록합니다.": "يُسجَّل عنصر بمجرد أن تحدّد الشاشة أن الخادم يحظر. تُسجَّل السبب نفسه مرة واحدة كل 5 دقائق كحد أقصى.",
  "음성 판독 (STT)": "الإملاء الصوتي (STT)",
  "인식 언어": "لغات التعرف",
  "마이크 아이콘 옆 언어 칩을 클릭하거나 Alt+L 을 누르면 선택한 언어들 사이에서 전환됩니다. 최소 2개 언어를 선택해야 합니다(기본: 한국어·영어).": "انقر شريحة اللغة بجانب أيقونة الميكروفون أو اضغط Alt+L للتبديل بين اللغات المحددة. يجب اختيار لغتين على الأقل (الافتراضي: الكورية والإنجليزية).",
  "음성 인식 언어 — 클릭 또는 Alt+L 로 전환 (설정>판독>음성 판독에서 언어 선택)": "لغة التعرف على الكلام — انقر أو اضغط Alt+L للتبديل (اختر اللغات من الإعدادات > القراءة > الإملاء الصوتي)",
  "자동 완성": "إكمال تلقائي",
  "문장 자동 완성": "إكمال الكلمات",
  "적용 범위": "النطاق",
  "과거 판독문": "التقارير السابقة",
  "단어 자동 완성 — 템플릿·과거 판독문 기반 예측, Enter 로 완성 (범위는 설정>판독>문장 자동 완성)": "إكمال الكلمات — تنبؤات من قوالبك وتقاريرك السابقة؛ اضغط Enter للقبول (النطاق في الإعدادات > القراءة > إكمال الكلمات)",
  "판독문 입력 중 예측 단어 표시 — Enter 로 완성 (판독창 상단 Word completion 체크와 연동)": "عرض الكلمات المتوقعة أثناء الكتابة — Enter للإكمال (مرتبط بمربع Word completion أعلى نافذة القراءة)",
  "초성(예: ㅍㄹ)이나 첫 글자를 입력하면 예측 단어가 나타나고, 계속 입력하면 후보가 좁혀집니다. 과거 판독문 어휘는 판독을 저장할 때마다 계정에 누적됩니다(기본 꺼짐).": "كتابة الحروف الأولى (مثل ㅍㄹ) تُظهر كلمات متوقعة؛ تابع الكتابة لتضييق المرشحين. تتراكم مفردات التقارير السابقة في حسابك مع كل حفظ (معطّل افتراضيًا).",
  "검사 코멘트": "تعليق الفحص",
  "병원 코멘트": "تعليق المستشفى",
  "통화 연결 (STUN/TURN)": "اتصال المكالمات (STUN/TURN)",
  "서로 다른 망(다른 건물·집) 사이의 화상·음성은 STUN/TURN 서버가 길을 찾아 줍니다. 지금 적용 중:": "بين الشبكات المختلفة (مبنى آخر أو منزل) تجد خوادم STUN/TURN مسار الصوت والصورة. المطبَّق الآن:",
