  "서버 설정": "إعداد الخادم",
  "기본 STUN": "STUN الافتراضي",
  "없음 (사설망)": "لا شيء (شبكة خاصة)",
  "있음": "موجود",
  "이 PC 설정 (비우면 서버·기본값 사용)": "هذا الجهاز (اتركه فارغًا لاستخدام الخادم/الافتراضي)",
  "이 PC 에 저장": "احفظ على هذا الجهاز",
  "서버 설정 (관리자) — 저장하면 모든 사용자에게 적용됩니다": "إعداد الخادم (مسؤول) — يسري على الجميع بعد الحفظ",
  "서버에 저장": "احفظ على الخادم",
  "서버에 저장했습니다 — 각 사용자의 다음 접속부터 적용됩니다": "حُفظ على الخادم — يسري من الاتصال التالي لكل مستخدم",
  "설정 삭제": "حذف الإعداد",
  "설정을 지우고 기본 동작(공인망=기본 STUN)으로 되돌립니다": "يزيل الإعداد ويعيد السلوك الافتراضي (عنوان عام = STUN افتراضي)",
  "JSON 형식이 올바르지 않습니다": "صيغة JSON غير صحيحة",
  "저장할 수 없습니다": "تعذّر الحفظ",
  "저장했습니다 — 다음 통화부터 적용됩니다": "حُفظ — يسري من المكالمة التالية",
  "STUN 만으로는 일부 망(대칭 NAT)을 넘지 못합니다 — 그때는 서버에 coturn 을 설치하고 turn: 주소를 등록하세요.": "لا يكفي STUN وحده لبعض الشبكات (NAT متماثل) — عندئذٍ ثبّت coturn على الخادم وسجّل عنوان :turn.",
  "통화 경로: 이 PC 설정": "مسار المكالمة: هذا الجهاز",
  "통화 경로: 서버 설정": "مسار المكالمة: إعداد الخادم",
  "통화 경로: 기본 STUN": "مسار المكالمة: STUN الافتراضي",
  "통화 경로: 없음 (사설망)": "مسار المكالمة: لا شيء (شبكة خاصة)",
  "상대와 미디어 경로를 찾지 못했습니다": "تعذّر العثور على مسار وسائط إلى الطرف الآخر",
  "연결 신호는 정상으로 오갔지만(서버·권한 문제 아님) 두 PC 사이에 영상·음성이 지나갈 네트워크 길이 없습니다. 서로 다른 망(다른 건물·집·통신사)이거나, 같은 망이라도 P2P 가 차단된 경우입니다.": "مرت إشارات الاتصال بشكل طبيعي (ليست مشكلة خادم أو أذونات)، لكن لا يوجد مسار شبكي للصوت والصورة بين الجهازين. هما على شبكتين مختلفتين (مبنى آخر، منزل، مشغّل) أو أن P2P محظور حتى داخل الشبكة نفسها.",
  "TURN 서버가 설정되어 있는데도 실패했습니다 — TURN 주소·계정이 맞는지, 서버 방화벽(3478/UDP·TCP)이 열려 있는지 확인하세요.": "فشل رغم إعداد خادم TURN — تحقّق من عنوان/حساب TURN وأن جدار حماية الخادم (3478/UDP·TCP) مفتوح.",
  "서버 관리자가 TURN 서버를 설치하고 Setting > 협진의 ICE 서버 설정에 등록해야 합니다. STUN 만으로는 일부 망(대칭 NAT)을 넘을 수 없습니다.": "يجب على مسؤول الخادم تثبيت خادم TURN وتسجيله في Setting > القراءة المشتركة (إعدادات ICE). لا يكفي STUN وحده لبعض الشبكات (NAT متماثل).",
  "Stack 동기 방식 (G 키)": "وضع مزامنة الكومة (G)",
  "Stack 동기 방식 (G 키) — Spatial: 같은 기준 좌표계·같은 단면 방향·겹치는 범위일 때 DICOM 좌표로 정합(그 밖에는 인덱스로 폴백하고 사유를 알립니다) / Index: 1:1 인덱스": "وضع مزامنة الكومة (G) — Spatial: المحاذاة بإحداثيات DICOM عند تطابق الإطار المرجعي واتجاه المقطع ونطاق التغطية (وإلا يعود إلى المزامنة بالفهرس مع بيان السبب) / Index: فهرس 1:1",
  "3D Cursor — 좌표계가 다르거나 촬영 범위 밖인 화면에는 표시하지 않았습니다": "المؤشر ثلاثي الأبعاد — لا يظهر في اللوحات ذات إطار مرجعي مختلف أو خارج نطاق التصوير",
  "3D Cursor — 이 영상에는 좌표 정보가 없어 다른 화면으로 연동하지 않습니다": "المؤشر ثلاثي الأبعاد — لا تحتوي هذه الصورة على بيانات إحداثيات، لذا لا ترتبط باللوحات الأخرى",
  "기준 좌표계(Frame of Reference)가 달라 좌표 정합을 쓸 수 없습니다 — 인덱스로 동기합니다": "إطار مرجعي مختلف — لا تصح المحاذاة بالإحداثيات، تتم المزامنة بالفهرس",
  "단면 방향이 달라 '같은 레벨'이 성립하지 않습니다 — 인덱스로 동기합니다": "اتجاه المقطع مختلف — لا يوجد مستوى مكافئ، تتم المزامنة بالفهرس",
  "겹치는 촬영 범위가 없어 좌표 정합을 쓸 수 없습니다 — 인덱스로 동기합니다": "لا يوجد تداخل في نطاق التصوير — تعذّرت المحاذاة بالإحداثيات، تتم المزامنة بالفهرس",
  "좌표 정보(DICOM 위치)가 없어 인덱스로 동기합니다": "لا توجد بيانات إحداثيات (موضع DICOM) — تتم المزامنة بالفهرس",
  "검색 UI 구성요소 표시/숨김": "عناصر واجهة البحث — إظهار/إخفاء",
  "Search Favorite 은 '센터#MR#병원명#미판독' 처럼 조건을 나열해 저장·재사용하는 검색입니다. 툴바 검색창 앞 💾 로 저장하면 좌측 목록에 쌓이고, ✏️ 로 수정 · 🗑️ 로 삭제합니다.": "يحفظ Search Favorite قائمة شروط مثل «مركز#MR#مستشفى#غير مقروء» لإعادة استخدامها. احفظ بزر 💾 بجوار مربع البحث؛ تظهر العناصر في القائمة اليسرى، ✏️ للتعديل و🗑️ للحذف.",
  "검색창 설정 — 통합 검색(FAV/SEARCH/AI)의 방식·범위": "مربع البحث — أسلوب ونطاق البحث الموحّد (FAV/SEARCH/AI)",
  "FAV — # 로 조건 나열 (기본)": "FAV — سرد الشروط بـ # (افتراضي)",
  "검색 방식 — FAV: '#' 로 조건 나열(상태·장비·모든 항목) · SEARCH: 선택한 범위에서 문법 검색(=정확/접두%/!제외/공백=다중어) · AI: 자연어를 필터로 변환": "أسلوب البحث — FAV: سرد الشروط بـ «#» (الحالة والجهاز وكل الأعمدة) · SEARCH: بحث بالصياغة ضمن النطاق المحدد (=مطابق / بادئة% / !استثناء / مسافة = عدة كلمات) · AI: يحوّل اللغة الطبيعية إلى مرشحات",
  "현재 검색식을 Search Favorite 로 저장 (예: 센터#MR#병원명#미판독)": "حفظ التعبير الحالي كـ Search Favorite (مثال: مركز#MR#مستشفى#غير مقروء)",
  "Search Favorite — 조건을 # 로 나열 (예: 센터#MR#병원명#미판독 · 항목=값 도 가능)": "Search Favorite — سرد الشروط بـ # (مثال: مركز#MR#مستشفى#غير مقروء · ويمكن عمود=قيمة)",
  "조건 나열": "شروط",
  "검색창 앞 💾 로 저장 — 예) 센터#MR#병원명#미판독": "احفظ بزر 💾 بجوار مربع البحث — مثال) مركز#MR#مستشفى#غير مقروء",
  "클릭=적용 · ✏️=수정 · 🗑️=삭제": "نقر = تطبيق · ✏️ = تعديل · 🗑️ = حذف",
  "저장할 검색식이 없습니다 — 예: 센터#MR#병원명#미판독": "لا يوجد تعبير للحفظ — مثال: مركز#MR#مستشفى#غير مقروء",
